window.ETC.igudziai = [
  {"id": 1, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "Pirminė paciento apžiūra – Primary Survey", "kam": "Visiems", "teorija": "Gyvybei pavojingų ir laikui jautrių problemų atpažinimas; ABCDE principas.", "praktika": "ABCDE praktika", "aprasymas": "<p>Pirminė paciento apžiūra skirta gyvybei pavojingoms, laikui jautrioms problemoms nustatyti. Tikslas – atkurti kraujo tūrį ir užtikrinti normalų deguonies tiekimą į audinius.</p><h3>Mokymosi temos</h3><a class=\"row\" href=\"#/p/eiga\">ETC eiga: nuo pranešimo iki antrinės apžiūros<span class=\"ar\">›</span></a>", "saltT": "ETC vadovas, 2 sk. „Sunkiai sužeisto paciento priėmimas ir gaivinimas“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=P2-cSPTPBHU", "title": "Environment Control & Zero Point Survey", "ch": "Cliff Reid", "note": "Pasiruošimas prieš atvykstant pacientui"}], "pastabos": "", "esme": ["Tikslas – iškart rasti ir koreguoti gyvybei pavojingas būkles. Prioritetai cABC: katastrofinis kraujavimas → kvėpavimo takai → krūtinė → šokas, toliau D ir E.", "Atvykus A (komandos vadas) atlieka 5 s apžiūrą pagal vertinimo trikampį: socialinė sąveika, kvėpavimo pastangos, odos perfuzija.", "5 s apžiūra atmeta katastrofinį kraujavimą, visišką kvėpavimo takų obstrukciją ir trauminį širdies sustojimą. Radus – garsiai Escape planas: pirma sprendžiama ši būklė.", "Po ATMIST – horizontali apžiūra: A – kvėpavimo takai, kaklo imobilizacija, deguonis, neurologija; B – visa apžiūra iki 2 min; C – iškart PVK / IO, kraujo grupė, gliukozė.", "B radinius praneša A baigęs visą apžiūrą, gyvybei pavojingus – iškart. Dubens diržą deda B ir C; nugarą (vertimas su C) apžiūri prieš e-FAST.", "Pacientą visiškai atidenkite, bet aktyviai saugokite nuo hipotermijos (priverstinio oro šildymo antklodė). Komunikacija – uždaro ciklo.", "Po apžiūros – apibendrinimas ir planas (≤ 5 min); įstrigus ar pablogėjus – STOP (10 s pauzė, ABCDE apžvalga). Vertinimas–gydymas–pakartotinis vertinimas."], "tccc": ["Apšaudymo metu (Care Under Fire) kvėpavimo takų valdymą paprastai geriausia atidėti iki Tactical Field Care fazės.", "TFC eiga: masyvus kraujavimas → kvėpavimo takai → kvėpavimas → kraujotaka → hipotermijos prevencija → galvos smegenų trauma."], "esmeSrc": ["ETC vadovas, 1 sk.", "ETC vadovas, 2 sk.", "ETC vertinimo lapas", "Kuopos ETC algoritmas (vaidmenys)", "TCCC 2026, CUF 7 p.; TFC 3–8 p.", "Flight Med – Ballistics Trauma (MARCH)"]},
  {"id": 2, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "Kvėpavimo takų atvėrimas su kaklo imobilizacija ir be jos", "kam": "Visiems", "teorija": "Indikacijos, padėtys, kaklo apsaugos principai.", "praktika": "Praktinis kvėpavimo takų atvėrimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku atverti kvėpavimo takus – kai kaklas imobilizuotas (su įtvaru) ir kai nėra kaklo traumos požymių</li></ul>", "saltT": "ETC vadovas, 3 sk. „Kvėpavimo takų valdymas traumos pacientui“", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Pirmiausia užkalbinkite („Ar viskas gerai?“) – aiškus atsakymas reiškia laisvus kvėpavimo takus. Kitaip – „žiūrėk, klausyk, jausk“.", "Pirmi veiksmai – smakro pakėlimas ir apatinio žandikaulio stūmimas. Po kiekvieno veiksmo vėl „žiūrėk, klausyk, jausk“.", "Įtariant kaklo traumą – MILS: rankos ant speninių ataugų, ausų neuždenkite, galva į neutralią padėtį be traukos; pacientui priešinantis jėgos nenaudokite.", "Kaklo traumos rizika – žandikaulio stūmimas, ne galvos atlošimas. Keliant smakrą kaklo pernelyg netieskite; lūžus žandikauliui stūmimas gali pabloginti obstrukciją.", "Nesant kaklo traumos rizikos – galvos atlošimas ir smakro pakėlimas; „uostymo“ padėtis: kaklas šiek tiek sulenktas, galva atlošta.", "Atvežtam su įtvaru: prieš jį atsegant kvėpavimo takų intervencijoms – MILS, laikoma, kol įtvaras vėl uždėtas. Atvėrus įtvarą su MILS reikia 3 žmonių.", "Įvertinus kvėpavimo takus MILS keičiamas pusiau standžiu kaklo įtvaru su blokais ir juostomis arba vakuuminiu čiužiniu (pagal vietines taisykles)."], "tccc": ["Sąmoningas gali užimti kvėpavimo takus geriausiai apsaugančią padėtį (ir sėdėti, pasilenkęs į priekį); nesąmoningas – šoninė padėtis, galva atlošta, smakras nuo krūtinės.", "Kaklo stuburo stabilizacija nebūtina, jei trauma tik penetruojanti."], "esmeSrc": ["ETC vadovas, 3 sk.", "Flight Med – Ballistics Trauma (MARCH)", "TCCC 2026, TFC 4 p. (Airway), 11 p."]},
  {"id": 3, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "Kvėpavimo takų atsiurbimas", "kam": "Visiems", "teorija": "Indikacijos, kontraindikacijos, sauga.", "praktika": "Atsiurbimo technika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku atsiurbti kvėpavimo takus</li></ul>", "saltT": "ETC vadovas, 3 sk. „Kvėpavimo takų valdymas traumos pacientui“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=8umlhqJ9Oq8", "title": "SALAD epistaxis", "ch": "Cliff Reid", "note": "Atsiurbimas, kai kvėpavimo takuose daug kraujo"}], "pastabos": "", "esme": ["Indikacija – kraujas, vėmalai, išskyros ar svetimkūniai burnoje; burbuliuojantis kvėpavimas rodo skystį viršutiniuose kvėpavimo takuose. Apžiūrėkite burną.", "Mažas kraujo ir išskyrų kiekis – atsiurbimo kateteris; didelis kraujo ar vėmalų kiekis – tvirtas plataus spindžio antgalis (Yankauer).", "Kietus svetimkūnius (maistą, dantis) šalinkite Magill žnyplėmis; kvėpavimo takuose esantis svetimkūnis turi būti pašalintas.", "Prieš dedant orofaringinį vamzdelį atverkite burną ir atsiurbkite, kad svetimkūniai nepatektų į gerklas.", "Atsiurbėjo veikimą patikrinkite prieš pacientui atvykstant. Prieš intubaciją – tvirtas atsiurbimas kraujui, išskyroms ir vėmalams pašalinti.", "Kraujuojant veidui ar kaklui padeda gravitacija: šoninė ar veidu žemyn padėtis, pažeista puse žemyn, išlaikant rankinę kaklo imobilizaciją.", "Nuolatinis kraujavimas į nosį ar burną – vien atsiurbimo neužtenka: pirmiausia užtikrinamas kvėpavimo takų praeinamumas (intubacija ar chirurginis), tada tamponada."], "tccc": ["Naudokite atsiurbimą, jei jis prieinamas ir tinkamas.", "Jei ankstesnės priemonės nesėkmingos, o obstrukcija (pvz., kraujas, veido lūžiai) nevaldoma – chirurginė krikotiroidotomija."], "esmeSrc": ["ETC vadovas, 3 sk.", "ETC vadovas, 2 sk.", "ETC vertinimo lapas", "Flight Med – Body Mechanics & Patient Packaging", "TCCC 2026, TFC 4 p. (Airway)"]},
  {"id": 4, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "Deguonies poreikio įvertinimas ir nenormalaus kvėpavimo atpažinimas", "kam": "Visiems", "teorija": "SpO₂, kvėpavimo dažnis, cianozė, obstrukcija, kvėpavimo darbas.", "praktika": "Vertinimo praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku įvertinti, ar pacientui reikia papildomai deguonies</li><li>Moku įvertinti ir atpažinti nenormalų kvėpavimą – per dažnas, apsunkintas, paviršinis / per retas / obstrukcinis kvėpavimas, cianozė</li></ul>", "saltT": "ETC vadovas, 3 sk. „Kvėpavimo takų valdymas traumos pacientui“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=PPXcsZ6hh6g", "title": "How to use a Patient Monitor", "ch": "EM3 Learn"}], "pastabos": "", "esme": ["Žiūrėkite: dažnas kvėpavimas (> 25/min), sujaudinimas ir prakaitavimas (hipoksija, hiperkapnija), pagalbiniai raumenys, įtraukos, cianozė.", "Klausykite: stridoras – obstrukcija gerklų lygyje ar aukščiau; švokštimas – apatiniai kvėpavimo takai; burbuliavimas – skystis; knarkimas – liežuvis ar gomurys.", "Visiška obstrukcija: paradoksiniai krūtinės ir pilvo judesiai, jokių garsų, oro srauto nejaučiama – skubiai atverti kvėpavimo takus.", "SpO₂ matuokite visiems. 90 % atitinka tik ~8 kPa (60 mmHg) PaO₂ – žemiau deguonies kiekis krenta staigiai. SpO₂ sumažėjus – deguonis.", "Pulsoksimetras nepatikimas esant vazokonstrikcijai, judesiams, anemijai, CO apsinuodijimui; nerodo ventiliacijos – esant daug O₂ gali būti hiperkapnija.", "Laisvi kvėpavimo takai negarantuoja pakankamos ventiliacijos (pvz., krūtinės trauma). Nepakankamas (paviršinis, retas) kvėpavimas ar apnėja – ventiliuokite ambu maišu.", "Eskaluokite (intubacija, DPV): kvėpavimo dažnis < 8 ar > 30/min, išsekimas, PaO₂ < 10 kPa esant dideliam O₂ srautui, kylantis PaCO₂ (> 6 kPa)."], "tccc": ["Pulsoksimetrija gali klaidinti esant šokui ar ryškiai hipotermijai; kvėpavimo takų praeinamumui vertinti – nuolatinė EtCO₂ ir SpO₂ stebėsena.", "Nepavykstant koreguoti hipoksijos ir SpO₂ krentant < 90 % (vid. / sunki galvos trauma – < 92 %) – apsvarstyti tinkamo dydžio NPA ir ventiliaciją 1000 ml ambu maišu."], "esmeSrc": ["ETC vadovas, 3 sk.", "ETC vadovas, 4 sk. (4.4 lent.)", "ETC vadovas, 2 sk.", "ETC įgūdžių įsivertinimas", "TCCC 2026, TFC 4–5 p."]},
  {"id": 5, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "Nosies kaniulių ir deguonies kaukės uždėjimas", "kam": "Visiems", "teorija": "Prietaisų pasirinkimas ir deguonies terapijos principai.", "praktika": "Prietaisų uždėjimas ir srauto nustatymas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku uždėti nosies kaniules</li><li>Moku uždėti deguonies kaukę</li></ul>", "saltT": "ETC vadovas, 3 sk. „Kvėpavimo takų valdymas traumos pacientui“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=rNnpiP6XEMg", "title": "How to set up Vapotherm", "ch": "EM3 Learn", "note": "Didelio srauto deguonis per nosies kaniules"}, {"url": "https://www.youtube.com/watch?v=92KWLX20gK4", "title": "How to set up an NIV", "ch": "EM3 Learn", "note": "Neinvazinė ventiliacija"}], "pastabos": "", "esme": ["Savarankiškai kvėpuojančiam, kai kvėpavimo takai laisvi, – gerai priglundanti kaukė su rezervuaru, 15 l/min. Rezervuarą pripildykite prieš uždėdami kaukę.", "Kaukė veikia tinkamai, kai rezervuaras su kiekvienu įkvėpimu dalinai subliūkšta, bet neištuštėja visiškai – kitaip didinkite srautą ar tikrinkite sandarumą.", "Nosies kaniulės – mažesniam poreikiui: srautas < 6 l/min (Flight Med: 2–6 l/min ≈ 24–44 % O₂). Didesniam poreikiui – kaukė, srautas > 6 l/min.", "Kaniulės: šakutes įkiškite į šnerves, vamzdelius užkabinkite už ausų ir po smakru, priveržkite tiek, kad būtų patogu.", "Poveikį stebėkite pagal SpO₂ ir kvėpavimo dažnį. Daug O₂ gaunančiam normali SpO₂ neatmeta hipoventiliacijos ir hiperkapnijos.", "Jei kvėpavimas nepakankamas ar jo nėra, vien kaukė nepadės – pradėkite ventiliaciją ambu maišu su deguonimi ir rezervuaru.", "Intubuojant nosies kaniulės (iki 15 l/min) naudojamos apnėjos oksigenacijai – ilgiau išvengiama desaturacijos."], "tccc": ["Daugumai kovos sužeistųjų papildomo O₂ nereikia; naudinga: maža SpO₂, oksigenaciją trikdantys sužalojimai, be sąmonės, galvos trauma, šokas, aukštis, dūmų įkvėpimas.", "Esant vidutinei ar sunkiai galvos traumai deguonis skiriamas, kad SpO₂ būtų ≥ 92 %."], "esmeSrc": ["ETC vadovas, 3 sk.", "ETC vertinimo lapas", "Flight Med – Airway Management", "TCCC 2026, TFC 5 p.; TACEVAC 4 p."]},
  {"id": 6, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "Nazofaringinio, orofaringinio vamzdelio ir laringinės kaukės parinkimas bei įdėjimas", "kam": "Visiems pagal kompetenciją", "teorija": "Indikacijos, kontraindikacijos ir parinkimas.", "praktika": "Prietaisų įdėjimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku įdėti nazofaringinį vamzdelį</li><li>Moku įdėti orofaringinį vamzdelį</li><li>Moku įdėti laringinę kaukę</li><li>Žinau, kokiu atveju naudočiau kiekvieną iš išvardintų priemonių</li></ul><h3>Mokymosi temos</h3><a class=\"row\" href=\"#/p/kvepavimas\">Kvėpavimo takai ir krūtinė<span class=\"ar\">›</span></a>", "saltT": "ETC vadovas, 3 sk. „Kvėpavimo takų valdymas traumos pacientui“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=9UyTlmjpeaI", "title": "Mastering the i-gel in Airway Management", "ch": "Cliff Reid"}], "pastabos": "", "esme": ["Orofaringinis – nesąmoningam be vėmimo reflekso. Dydis: nuo kandžių iki apatinio žandikaulio kampo. Įveskite apverstą iki minkštojo gomurio, pasukite 180°.", "Atsiradus vėmimo refleksui ar įsitempus – orofaringinį ištraukite. Jį toleruojantis pacientas turi neapsaugotus kvėpavimo takus – planuokite pažangią priemonę.", "Nazofaringinis geriau toleruojamas, kai sąmonė sutrikusi negiliai; tinka esant trizmui. Nedėkite esant žinomam ar įtariamam kaukolės pamato lūžiui.", "Nazofaringinis: ilgis – nuo ausies spenelio iki šnervės; sutepkite, kiškite palei nosies dugną (ne aukštyn), pirmiausia į dešinę šnervę.", "Laringinė kaukė (supraglotinė priemonė) – kai bazinės priemonės ar ventiliacija nepakankamos, o intubuoti iš karto negalima, ar intubacija nepavyko.", "Laringinės kaukės dydis – pagal gamintoją (ETC: klasikinė – vyrams 5, moterims 4). Išlaikykite MILS. Nepavyko per 30 s – ventiliuokite ambu maišu, tada vėl.", "Po įdėjimo: krūtinė turi kilti abipus; nedidelis nuotėkis leistinas, didelis girdimas – bloga padėtis. Įdėkite kandiklį, pritvirtinkite, įveskite skrandžio zondą."], "tccc": ["SpO₂ krentant < 90 % (galvos trauma – < 92 %) ir hipoksijos nepavykstant koreguoti – apsvarstyti tinkamo dydžio NPA ir ventiliaciją 1000 ml ambu maišu.", "Nevaldomai obstrukcijai (veido lūžiai, tiesioginis kvėpavimo takų sužalojimas, kraujas, deformacija, nudegimai) – chirurginė krikotiroidotomija."], "esmeSrc": ["ETC vadovas, 3 sk.", "Flight Med – Airway Management", "TCCC 2026, TFC 4–5 p."]},
  {"id": 7, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "Ambu maišo naudojimas ir ventiliacija", "kam": "Visiems", "teorija": "Ventiliacijos ambu maišu principai, kaukės sandarumas, ventiliacijos vertinimas.", "praktika": "BVM ventiliacija", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku naudotis ambu maišu ir ventiliuoti naudojant ambu maišą</li></ul>", "saltT": "ETC vadovas, 3 sk. „Kvėpavimo takų valdymas traumos pacientui“", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Indikacija – nepakankamas ar nesantis kvėpavimas, nors kvėpavimo takai laisvi. Kaukė turi dengti nosį ir burną.", "Vienas: kaukė viena ranka (C–E), žandikaulio stūmimu veidą kelkite į kaukę, kita ranka spauskite maišą. Tai sunku – geriau dirbti dviese.", "Dviese: vienas abiem rankomis laiko kaukę ir stumia žandikaulį, kitas spaudžia maišą. Efektyviai ventiliacijai kauke reikia dviejų žmonių.", "Be deguonies maišas tiekia orą (21 % O₂); prijungus didelį O₂ srautą ir rezervuarą – iki maždaug 80 %.", "Stebėkite krūtinės kilimą, SpO₂, EtCO₂. Nuotėkis – hipoventiliacija; nekompensuokite stipriu spaudimu: oras patenka į skrandį, didėja aspiracijos rizika.", "Svarbiausia – kaukės sandarumas ir tinkamas dažnis. Dažna klaida – per didelė ventiliacija; jei yra EtCO₂, ventiliaciją derinkite pagal jį.", "Esant kaklo traumos rizikai ventiliuokite išlaikydami galvos ir kaklo ašį. Dažnai prireiks pažangios priemonės – prie jos jungiamas tas pats maišas."], "tccc": ["Neištaisomai hipoksijai (SpO₂ < 90 %, galvos trauma – < 92 %) – apsvarstyti NPA ir ventiliuoti 1000 ml ambu maišu.", "Galvos trauma: ventiliuojamam siekti EtCO₂ 35–45 mmHg; be EtCO₂ – mažas kvėpavimo tūris, 10 įkvėpimų/min (kas 6 s)."], "esmeSrc": ["ETC vadovas, 3 sk.", "Flight Med – Airway Management", "TCCC 2026, TFC 5, 8 p."]},
  {"id": 8, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "Neefektyvaus kvėpavimo takų valdymo atpažinimas", "kam": "Visiems", "teorija": "Kada reikia eskaluoti pagalbą.", "praktika": "Ventiliacijos efektyvumo vertinimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku įvertinti, ar mano taikomi kvėpavimo takų valdymo veiksmai gerina plaučių ventiliaciją ir deguonies kiekį kraujyje</li><li>Galiu atpažinti, kada mano taikomi kvėpavimo takų valdymo veiksmai yra neefektyvūs ir reikia kviesti ekspertinę pagalbą intubacijai</li></ul><h3>Mokymosi temos</h3><a class=\"row\" href=\"#/p/kvepavimas\">Kvėpavimo takai ir krūtinė<span class=\"ar\">›</span></a>", "saltT": "ETC vadovas, 3 sk. „Kvėpavimo takų valdymas traumos pacientui“", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Po kiekvieno veiksmo vėl „žiūrėk, klausyk, jausk“, stebėkite SpO₂ ir EtCO₂. Dažna klaida – neatpažinta nepakankama oksigenacija ar ventiliacija.", "Neefektyvumo požymiai: išlieka triukšmingas kvėpavimas ar paradoksiniai judesiai, krūtinė nekyla, SpO₂ nekyla ar krenta, didelis nuotėkis, pučiasi skrandis.", "Eskalavimas: atsiurbti → optimizuoti atvėrimą (nesąmoningam – orofaringinis) → orofaringinį keisti laringine kauke; kartu didinti O₂ srautą.", "Kartu kvieskite ekspertinę pagalbą intubacijai; jei patys intubuoti neturite įgūdžių – skubiai kvieskite anesteziologą.", "Pažangios priemonės reikia: bazinės nepakankamos, toleruojamas orofaringinis, gresia tinimas (nudegimai), krūtinės trauma, galvos trauma (pCO₂ kontrolė).", "Nepavykstant – A garsiai skelbia didelės rizikos krikotiroidotomijos situaciją, B ruošia rinkinį. Sprendimą aiškiai paskelbkite ir vykdykite nedelsiant.", "Nekartokite nepasiteisinusios technikos: išnaudojus geriausias pastangas (kaukė, laringinė kaukė, intubacija) – CICO, skubi krikotiroidotomija. Klaida – delsti."], "tccc": ["Dažnai pakartotinai vertinkite SpO₂, EtCO₂ ir kvėpavimo takų praeinamumą – jų būklė laikui bėgant gali keistis.", "Ankstesnėms priemonėms nepadėjus ir obstrukcijos (veido lūžiai, kvėpavimo takų sužalojimas, kraujas, deformacija, nudegimai) nesuvaldžius – chirurginė krikotiroidotomija."], "esmeSrc": ["ETC vadovas, 3 sk.", "ETC vertinimo lapas", "TCCC 2026, TFC 4 p. (Airway)"]},
  {"id": 9, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "Sunkūs kvėpavimo takai ir periintubacinė rizika", "kam": "Intubuojantiems gydytojams", "teorija": "Sunkūs kvėpavimo takai, fiziologinė rizika, optimizavimas.", "praktika": "Algoritmų praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Galiu atpažinti sunkius kvėpavimo takus</li><li>Suprantu periintubacinę riziką ir galiu ją valdyti dekompensuotiems pacientams</li><li>Žinau, kokių priemonių reikia intubuojant pacientą</li></ul>", "saltT": "ETC vadovas, 3 sk. „Kvėpavimo takų valdymas traumos pacientui“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=BUh5wmWN4SA", "title": "Epiglottic abscess", "ch": "Cliff Reid", "note": "Netikėtai sunkūs kvėpavimo takai"}], "pastabos": "", "esme": ["Sunki oksigenacija kauke: veido trauma, kaklo įtvaras, kraujas ar vėmalai viršutiniuose kvėpavimo takuose, anomalijos, išsekimas, nutukimas, barzda.", "Sunki laringoskopija: ribotas kaklo judrumas, išsikišę kandžiai, atsitraukęs žandikaulis, didelis liežuvis, randai, tinimas, veido ar kaklo trauma, įtvaras.", "Numatant sunkumus intubuoja tik patyręs specialistas su tinkama įranga; vienintelė išimtis – tiesioginė grėsmė gyvybei.", "Šoke indukcijos vaistai veikia vėliau – per anksti kartojant dozę gresia kraujotakos kolapsas. Teigiamo slėgio ventiliacija mažina veninį grįžimą.", "Hipotenzija po indukcijos – dažnai hipovolemija ar ventiliuojant atsiradęs įtampinis pneumotoraksas: krūtinės dekompresija, masinė transfuzija, vazopresoriai.", "Preoksigenacija – 3 min 100 % O₂; kritinės būklės, nutukę, senyvi desaturuoja greičiau. Apnėjos oksigenacija per nosies kaniules; SpO₂ ≤ 92 % – iškart ventiliuoti.", "Prieš indukciją: 2 didelio spindžio PVK, užfiksuoti GKS, kairės–dešinės skirtumas ir vyzdžiai, AMPLE, RSI kontrolinis sąrašas, paruoštas vazopresorius."], "tccc": [], "esmeSrc": ["ETC vadovas, 3 sk.", "ETC vadovas, 2 sk."]},
  {"id": 10, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "RSI, MILS, nesėkmingos intubacijos ir CICO principai", "kam": "Intubuojantiems gydytojams", "teorija": "RSI principai, MILS, intubacijos nesėkmės algoritmai.", "praktika": "Komandos treniruotė", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Žinau, kas yra MILS (Manual In-Line Stabilisation) intubuojant su kaklo įtvaru</li><li>Moku parinkti tinkamus vaistus ir dozes greitos eigos indukcijai ir intubacijai (RSI), atsižvelgiant į paciento fiziologinius parametrus</li><li>Žinau, ką daryčiau nesugebėdamas intubuoti iš pirmo / antro karto: optimizuoti galvos padėtį, pakeisti priemones efektyvesnėmis, optimizuoti sedaciją / relaksaciją</li><li>Žinau, ką daryčiau, jei po nesėkmingos intubacijos negaliu oksigenuoti per sandarią kaukę</li><li>Žinau, ką daryčiau, jei negalėčiau nei intubuoti, nei oksigenuoti (CICO)</li></ul>", "saltT": "ETC vadovas, 3 sk. „Kvėpavimo takų valdymas traumos pacientui“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=XV9JLihcdb4", "title": "Surgical Airway Mindset and Preparation", "ch": "Cliff Reid"}], "pastabos": "", "esme": ["Sunkios traumos atveju – RSI; atlieka tik apmokyti, kompetentingi vartoti anestetikus. Kontrolinis sąrašas – visada, išskyrus mirštantį ar ištiktą širdies sustojimo.", "Traumos RSI – iki 4 žmonių: intubuojantis, MILS, vaistai, krikoidinis spaudimas (pagal vietinę praktiką; netaikyti esant aktyviam vėmimui).", "MILS: padėjėjas klūpo šone ir laiko galvą už speninių ataugų; nuimamos juostos, blokai ir įtvaro priekis. Su uždėtu įtvaru laringoskopijos nebandykite.", "Taikant MILS gerklų vaizdas blogesnis – bužas ar stiletas būtini. Indukcinis vaistas, iškart po jo raumenų relaksantas – į veikiančią IV liniją.", "ETV padėtį patvirtinkite kapnografija (bronchinės intubacijos ji neatskiria), simetriškais krūtinės judesiais, auskultacija pažastyse ir virš skrandžio.", "Prieš indukciją sutarkite planą: RSI → kaukė / laringinė kaukė → priekinė kaklo prieiga (FONA). Vortex: ne daugiau 3 bandymų kiekvienam iš 3 būdų.", "CICO: 10 s pauzė, aiškiai paskelbti ir nedelsiant atlikti skalpelio–bužo–vamzdelio (6,0 mm su manžete) krikotiroidotomiją; padėtį patvirtinti kapnografija."], "tccc": ["TACEVAC metu, jei apmokytas, vietoje krikotiroidotomijos galima svarstyti endotrachėjinę intubaciją.", "Krikotiroidotomija – bužo pagalba ar atvira technika; kaniulė su flanšu ir manžete (išorinis skersmuo < 10 mm, vidinis 6–7 mm); padėtis – nuolatine EtCO₂ kapnografija."], "esmeSrc": ["ETC vadovas, 3 sk.", "TCCC 2026, TFC 4 p.; TACEVAC 3 p."]},
  {"id": 11, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "Pointubacinė analgosedacija ir DPV pagrindai", "kam": "Intubuojantiems gydytojams", "teorija": "Sedacija, adaptacija prie DPV, baziniai ventiliacijos parametrai.", "praktika": "Ventiliatoriaus valdymo praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Žinau, kokius vaistus ir dozes skirti pointubacinei analgosedacijai / adaptacijai prie DPV</li><li>Turiu bazinių žinių ir įgūdžių nustatant DPV parametrus, žinau, kokiu režimu ventiliuočiau pacientą</li><li>Suprantu plaučių fiziologiją, moku atpažinti ir koreguoti ventiliatoriaus problemas (pvz., pagal DOPES algoritmą)</li></ul>", "saltT": "ETC vadovas, 3 sk. „Kvėpavimo takų valdymas traumos pacientui“", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Kaip palaikysite anesteziją po indukcijos, numatykite dar prieš RSI (kontrolinis sąrašas). Vaistus titruokite – pvz., ketaminas, fentanilis, morfinas.", "Hipertenzija po intubacijos gali reikšti nepakankamą sedaciją ar analgeziją; hipotenzija – vaistų poveikį ar hipovolemiją.", "Po intubacijos: pritvirtinkite ETV, patikrinkite gylį (virš bifurkacijos), orofaringinis – kaip kandiklis, skrandžio zondas; stebėkite ritmą, SpO₂, AKS, EtCO₂.", "Didėjant intrakranijiniam spaudimui ETV tvirtinkite lipnia juosta, ne raišteliu (nespausti jungo venų); galvūgalis pakeltas 30° (TCCC – jei nėra šoko).", "DPV padeda išvengti hiper- ir hipoventiliacijos; jį nustato apmokytas asmuo, individualiai, pagal dažną arterinio kraujo dujų tyrimą.", "Krūtinės trauma, plaučių sumušimas – plaučius sauganti ventiliacija (tariantis su intensyviąja terapija). Po sprogimo teigiamas slėgis didina oro embolijos riziką.", "Staigus pablogėjimas DPV metu – tikrinkite pagal DOPES: ETV padėtį (stemplė, bronchas) ir įtampinį pneumotoraksą – teigiamas slėgis jį greitai sunkina."], "tccc": ["Galvos trauma: ventiliuojamam siekti EtCO₂ 35–45 mmHg; be EtCO₂ – mažas kvėpavimo tūris, 10 įkvėpimų/min (kas 6 s).", "Visiems, gavusiems stiprių analgetikų, atidžiai stebėti kvėpavimo takus, kvėpavimą ir kraujotaką."], "esmeSrc": ["ETC vadovas, 3 sk.", "ETC vadovas, 4 sk.", "ETC vadovas, 2 sk.", "ETC vertinimo lapas", "ETC įgūdžių įsivertinimas", "TCCC 2026, TFC 8, 11 p."]},
  {"id": 12, "sritis": "Pirminė apžiūra", "potema": "A (Airway)", "pav": "Vyzdžiai, AVPU, galūnių simetrija ir GKS", "kam": "Visiems / medicinos personalui", "teorija": "Sąmonės ir neurologinio statuso vertinimas.", "praktika": "Neurologinio vertinimo praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku įvertinti vyzdžius ir jų reakciją į šviesą</li><li>Moku įvertinti paciento sąmonės būklę pagal AVPU</li><li>Galiu įvertinti, ar pacientas judina visas galūnes simetriškai</li><li>Moku įvertinti paciento sąmonę pagal GKS (Glasgow Coma Scale) – medicinos personalui</li></ul>", "saltT": "ETC vadovas, 2 sk. „Sunkiai sužeisto paciento priėmimas ir gaivinimas“; 8 sk. „Galvos trauma“", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Pirminėje apžiūroje neurologiją (D) vertina A: AVPU, vyzdžių dydis, simetrija ir reakcija į šviesą, galūnių judesių simetrija.", "AVPU: A – budrus, V – reaguoja į balsą, P – reaguoja į skausmą, U – nereaguoja.", "Palyginkite motorinį atsaką visose keturiose galūnėse – ryškus skirtumas yra lateralizacijos požymis.", "GKS (medicinos personalui) įvertinkite ir kartokite – pirminėje, antrinėje apžiūroje ir būklei pablogėjus; registruokite dinamiką.", "Prieš sedaciją ar RSI užfiksuokite GKS, kairės–dešinės skirtumą ir vyzdžius; nugaros smegenų pažeidimo požymiai – diafragminis kvėpavimas, vazodilatacija, priapizmas.", "Sutrikus sąmonei – žiūrėkite gliukozę (C ją nustato visiems), atmeskite hipoksiją ir šoką: pakitusi sąmonė be galvos traumos – hemoraginio šoko požymis.", "Raudonos vėliavos – asimetriški ar fiksuoti išsiplėtę vyzdžiai, patologinė pozicija (išvaržos požymiai), blogėjanti neurologinė būklė: eskaluokite nedelsiant."], "tccc": ["Vid. / sunki galvos trauma: negali vykdyti paprastų komandų (nykštys aukštyn, du pirštai, mirktelėti) > 10 min po traumos IR įtariama galvos trauma.", "Abejojant dėl neurologinių pakitimų priežasties – gydyti hemoraginį šoką; neurologinę būklę vertinti kas 5–10 min; prieš ketaminą užrašyti AVPU."], "esmeSrc": ["ETC vadovas, 2 sk.", "ETC vadovas, 3 sk.", "ETC vertinimo lapas", "ETC traumos kortelė", "Kuopos ETC algoritmas (vaidmenys)", "TCCC 2026, TFC 3, 6, 8, 11 p."]},
  {"id": 13, "sritis": "Pirminė apžiūra", "potema": "B (Breathing)", "pav": "Krūtinės ląstos apžiūra, palpacija, perkusija ir auskultacija", "kam": "Medicinos personalui", "teorija": "Poodinė emfizema, flail chest, žaizdos, kvėpavimo patologija.", "praktika": "Krūtinės ląstos vertinimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku atlikti krūtinės ląstos apžiūrą: žinau, kas yra poodinė emfizema, nestabili krūtinės ląsta (flail chest), moku perkutuoti / auskultuoti plaučius, apžiūrėti dėl žaizdų</li></ul><h3>Mokymosi temos</h3><a class=\"row\" href=\"#/p/kvepavimas\">Kvėpavimo takai ir krūtinė<span class=\"ar\">›</span></a>", "saltT": "ETC vadovas, 4 sk. „Kvėpavimo sutrikimai ir krūtinės ląstos trauma“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=cpKpAyNnZzQ", "title": "Ultrasound Podcast - Lung Ultrasound Basics part 1: Pneumothorax and Pulmonary Edema", "ch": "Core Ultrasound", "note": "Papildomai: pneumotoraksas ultragarsu"}], "pastabos": "", "esme": ["B atmeta 6 būkles: kvėpavimo takų obstrukciją / pažeidimą, įtampos pneumotoraksą, atvirą krūtinės žaizdą, masyvų hemotoraksą, nestabilią krūtinės ląstą, tamponadą.", "Apžiūra: žaizdos, kraujosruvos, kilnojimosi simetrija, paradoksalūs judesiai, kvėpavimo dažnis ir pastangos. Kakle – trachėjos padėtis, žaizdos, hematomos.", "Palpacija: skausmingumas, krepitacija, poodinė emfizema (pneumotoraksas, kvėpavimo takų plyšimas). Auskultuokite 3 taškuose kiekvienoje pusėje ir lyginkite.", "Dėžinis garsas ir susilpnėję kvėpavimo garsai – pneumotoraksas; duslus garsas, susilpnėję garsai ir šokas – masyvus hemotoraksas.", "Nestabili krūtinės ląsta (flail chest) – ≥ 2 gretimi šonkauliai lūžę ≥ 2 vietose. Jaunam paradoksalus judesys gali išryškėti tik pacientui pavargus.", "Krūtinės, kaklo ar viršutinės pilvo dalies žaizda – įtarkite tamponadą; ypač centrinėje krūtinėje („pavojinga zona“), priekyje ir nugaroje.", "Trachėjos nukrypimas – vėlyvas, nepatikimas požymis. Iškart po traumos radiniai gali būti normalūs – kartokite. Gyvybei pavojingą radinį B praneša A iškart."], "tccc": ["Įtampos pneumotoraksas: liemens ar pirminė sprogimo trauma + dusulys / tachipnėja, vienpusiai silpni ar nėra kvėpavimo garsų, SpO₂ < 90 %, šokas ar trauminis širdies sustojimas.", "Atvirą ar „siurbiančią“ krūtinės žaizdą iškart uždengti vožtuviniu okliuziniu tvarsčiu (nesant – nevožtuviniu) ir stebėti, ar nesivysto įtampos pneumotoraksas."], "esmeSrc": ["ETC vadovas, 4 sk.", "ETC vadovas, 2 sk. (priedas)", "ETC vertinimo lapas (B narys)", "TCCC 2026, TFC 5 (Respiration)", "Flight Med – Ballistics Trauma", "Kuopos ETC algoritmas"]},
  {"id": 14, "sritis": "Pirminė apžiūra", "potema": "B (Breathing)", "pav": "Pleuros drenavimas ir Bobrovo aparato principas", "kam": "Pagal kompetenciją", "teorija": "Indikacijos, komplikacijos, analgezija.", "praktika": "Pleuros drenavimo praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku atlikti pleuros drenavimą ir adekvačiai nuskausminti procedūros vietą. Žinau, kas yra Bobrovo aparatas</li></ul><h3>Mokymosi temos</h3><a class=\"row\" href=\"#/p/kvepavimas\">Kvėpavimo takai ir krūtinė<span class=\"ar\">›</span></a>", "saltT": "ETC vadovas, 4 sk. „Kvėpavimo sutrikimai ir krūtinės ląstos trauma“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=co9_RLN78IY", "title": "Tension Pneumothorax and Needle Thoracostomy", "ch": "Larry B. Mellick, MD"}, {"url": "https://www.youtube.com/watch?v=ExAKcElqCDo", "title": "Pigtail Catheter Placement for Traumatic Pneumothorax", "ch": "Larry B. Mellick, MD"}], "pastabos": "", "esme": ["Indikacijos – pneumotoraksas (paprastas ir įtampos) ir hemotoraksas. Ventiliuojamam įtampos pneumotoraksas – iškart šoninė torakostomija, po jos drenas.", "Vieta – 5-asis tarpšonkaulinis tarpas (ar aukščiau), 1 cm prieš vidurinę pažasties liniją, ranka atitraukta. Jei apmokytas – vietą patikrinkite ultragarsu.", "Pirštinė torakostomija (be dreno) – greita diagnostinė ir gydomoji dekompresija; būklei vėl blogėjant, pirštą per pjūvį įkiškite pakartotinai.", "Atvira technika, bukas preparavimas. Drenas 28–32 Fr jungiamas prie užpildytos ir teisingai sumontuotos povandeninės drenažo sistemos (vandens užraktas).", "Sąmoningam – paaiškinkite, gaukite sutikimą, infiltruokite vietinį anestetiką odoje, poodyje iki pleuros; svarstykite serratus anterior / erector spinae blokadą.", "Prieš drenuojant – veikianti IV prieiga: išleidus hemotoraksą kraujavimas gali atsinaujinti. Per dreną > 200 ml/val. – skubiai chirurgas (torakotomija).", "Komplikacijos: kraujavimas, tarpšonkaulinių kraujagyslių ir nervo, krūtinės ir pilvo organų pažeidimas, infekcija. Dažna klaida – drenas ne pleuroje ar iškrenta."], "tccc": ["Adatos dekompresija pažeistoje pusėje: 14G ar 10G, 3,25 col.; 5 tarpšonkaulis priekinėje pažasties linijoje (ne mediališkiau spenelio) arba 2 – vid. raktikaulio linijoje.", "Refrakteriniam šokui – pakartotinė dekompresija arba pirštinė torakostomija / drenas 5 tarpšonkaulyje priekinėje pažasties linijoje; pirštinė anga gali užsiverti."], "esmeSrc": ["ETC vadovas, 4 sk.", "ETC vadovas, 2 sk.", "ETC įgūdžių įsivertinimas (regioninės blokados)", "TCCC 2026, TFC 5 (Respiration), 6f (Refractory Shock)"]},
  {"id": 15, "sritis": "Pirminė apžiūra", "potema": "B (Breathing)", "pav": "Monitoriaus elektrodai, pulsoksimetras ir AKS", "kam": "Visiems", "teorija": "Monitoravimo principai ir rodmenų interpretacija.", "praktika": "Monitoravimo įrangos uždėjimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku uždėti monitoriaus elektrodus, pulsoksimetrą, manžetę AKS matavimui ir vertinti monitoriaus rodmenis</li></ul><h3>Mokymosi temos</h3><a class=\"row\" href=\"#/p/isdestymas\">Darbo vietos išdėstymas<span class=\"ar\">›</span></a>", "saltT": "ETC vadovas, 2 sk. „Sunkiai sužeisto paciento priėmimas ir gaivinimas“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=PPXcsZ6hh6g", "title": "How to use a Patient Monitor", "ch": "EM3 Learn"}], "pastabos": "", "esme": ["B uždeda EKG ir SpO₂, C – AKS manžetę ir vertina kapiliarų prisipildymą; A stebi iškvepiamo CO₂ kiekį (kapnografija).", "ŠSD tikrinkite iš 3 nepriklausomų šaltinių (EKG, pulsoksimetras, AKS matuoklis), ritmą – iš EKG ir pulsoksimetro; neatitikimą išsiaiškinkite.", "Žemo AKS nenurašykite artefaktui (pvz., per didelei manžetei) – traumos atveju labiausiai tikėtina hipotenzijos priežastis yra hipovoleminis šokas.", "Rodmenis derinkite su klinika: šaltos, marmurinės, prakaituotos galūnės, silpnas radialinis ar šlaunies pulsas – šoko požymiai.", "SpO₂ rodmenys gali klaidinti esant šokui ar ryškiai hipotermijai. Sumažėjus SpO₂ – deguonis.", "Sekite tendencijas ir registruokite rodmenis; vertinkite po kiekvienos intervencijos – lėtus pokyčius lengva praleisti.", "Sunki krūtinės trauma (flail, plaučių sumušimas), įtariamas aortos pažeidimas ar vazoaktyvūs vaistai – arterinė linija (tikslesnis AKS, kraujo dujos)."], "tccc": ["Pradėti pulsoksimetriją; visus su vidutine ar sunkia galvos smegenų trauma stebėti pulsoksimetru. Rodmenys gali klaidinti esant šokui ar ryškiai hipotermijai."], "esmeSrc": ["ETC vadovas, 2 sk.", "ETC vadovas, 1 sk. (žmogiškieji veiksniai)", "ETC vadovas, 4 sk.", "ETC vertinimo lapas (C narys)", "TCCC 2026, TFC 5c", "Flight Med – Art Lines"]},
  {"id": 16, "sritis": "Pirminė apžiūra", "potema": "B (Breathing)", "pav": "e-FAST ultragarsinis tyrimas", "kam": "Pagal kompetenciją", "teorija": "Laisvas skystis, pneumotoraksas / hemotoraksas, perikardas.", "praktika": "e-FAST praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku atlikti e-FAST ištyrimą ultragarsu: laisvas skystis pilvo ertmėje (+/- perikarde), pneumotoraksas / hemotoraksas</li></ul>", "saltT": "ETC vadovas, 2 sk. „Sunkiai sužeisto paciento priėmimas ir gaivinimas“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=zpL9iZCbx68", "title": "Ultrasound Podcast - EFAST - Let's put the fun back in fundamentals!", "ch": "Core Ultrasound"}, {"url": "https://www.youtube.com/watch?v=RLxK2fPHAhk", "title": "Ultrasound Podcast - Lung Ultrasound Part 3: Advanced pneumothorax pro tips", "ch": "Core Ultrasound"}, {"url": "https://www.youtube.com/watch?v=FXRTM-1aUhE", "title": "The POCUS diagnosis of a Pericardial Effusion: A Practical Guide for Clinicians", "ch": "Core Ultrasound"}, {"url": "https://www.youtube.com/watch?v=qvNFSO8P57U", "title": "Ultrasound Podcast - Cliff Reid on EFAST", "ch": "Core Ultrasound"}], "pastabos": "", "esme": ["e-FAST – greita gyvybei pavojingų būklių ir šoko priežasties paieška; ypač vertingas hemodinamiškai nestabiliam. Stabiliam aukso standartas – KT.", "Pilvas: Morisono (hepatorenalinė) kišenė, periblužninė / splenorenalinė sritis, šlapimo pūslės sritis (už pūslės, Duglaso įduba) – laisvas skystis.", "Širdis (subksifoidinis vaizdas): skystis perikarde, dešiniojo skilvelio suspaudimas – tamponada. Penetruojančiai traumai pradėkite nuo širdies.", "Krūtinė abipus: nėra pleuros slydimo ir B linijų, matomos A linijos – pneumotoraksas. Ultragarsas pneumo- ir hemotoraksą nustato tiksliau nei rentgenas.", "Neigiamas e-FAST kraujavimo neatmeta: nepatyręs tyrėjas laisvą skystį dažnai pamato tik nuo ~500 ml (patyręs – nuo ~100 ml).", "Po gaivinimo kolabuojanti apatinė tuščioji vena ir tuščia šlapimo pūslė – nepakankamas gaivinimas arba tęsiasi kraujavimas.", "Kuopoje e-FAST (pagal kompetenciją) atlieka B – tik po nugaros apžiūros; radinius praneša A. Laisvas skystis stabiliam – skubi KT."], "tccc": [], "esmeSrc": ["ETC vadovas, 2 sk.", "ETC vadovas, 4 sk.", "Flight Med – Ballistics Trauma (E-FAST)", "ETC vertinimo lapas (B narys)", "Kuopos ETC algoritmas"]},
  {"id": 17, "sritis": "Pirminė apžiūra", "potema": "B (Breathing)", "pav": "Dubens diržas ir paciento vertimas ant šono", "kam": "Visiems pagal situaciją", "teorija": "Indikacijos ir saugus mobilizavimas.", "praktika": "Praktinė technika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku paversti pacientą ant šono</li><li>Moku uždėti dubens diržą dubens imobilizacijai</li></ul>", "saltT": "ETC vadovas, 7 sk. „Dubens trauma“", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Vertimas ant šono („rąstu“) – apžiūrėti visą nugarą ir sėdmenis (žaizdos, kraujavimas), pašalinti nuolaužas; sąmoningam – čiuopti stuburo vidurio liniją.", "Penetruojanti (durtinė, šautinė) trauma – nugaros apžiūra ypač svarbi. Radus krūtinės ląstos žaizdą (ir nugarinėje pusėje) – okliuzinis tvarstis.", "Kuopoje B ir C verčia kartu, nugarą apžiūri B – prieš e-FAST; radiniai pranešami A.", "Įtariant stuburo traumą – galva ir kaklas stabilizuojami rankomis, verčiama be nekontroliuojamų stuburo judesių.", "Hipovolemija ar nestabilus dubuo – vertimas gali destabilizuoti kraujotaką ar išstumti krešulį: verskite atsargiai ir minimaliai, bet nugaros žaizdų nepraleiskite.", "Dubens diržas – kai dubuo nestabilus ar tarpvietėje yra kraujo; deda B kartu su C (žr. #20).", "Kuo anksčiau nukelkite nuo stuburo lentos ar mentinių neštuvų – mažiau skausmo ir pragulų rizika."], "tccc": ["Dubens diržas įtarus lūžį: sunki buka ar sprogimo trauma + dubens skausmas, didelė apatinės galūnės (beveik) amputacija, lūžio požymiai, be sąmonės ar šokas."], "esmeSrc": ["ETC vadovas, 2 sk.", "ETC vadovas, 3 sk. (stuburo apsauga)", "ETC vertinimo lapas (B ir C nariai)", "Flight Med – Ballistics / Blast Injuries", "TCCC 2026, TFC 6a.1", "Kuopos ETC algoritmas"]},
  {"id": 18, "sritis": "Pirminė apžiūra", "potema": "B (Breathing)", "pav": "Krikotiroidotomija", "kam": "Pagal kompetenciją", "teorija": "CICO situacijos ir procedūros principai.", "praktika": "Procedūros treniruoklis", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku atlikti krikotiroidotomiją (idealiu atveju chirurgiškai – su skalpeliu, bužu ir ETV)</li></ul><h3>Mokymosi temos</h3><a class=\"row\" href=\"#/p/kvepavimas\">Kvėpavimo takai ir krūtinė<span class=\"ar\">›</span></a>", "saltT": "ETC vadovas, 3 sk. „Kvėpavimo takų valdymas traumos pacientui“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=ezxwuCaf7J0", "title": "Scalpel-Finger-Bougie Cricothyrotomy Technique", "ch": "Larry B. Mellick, MD"}, {"url": "https://www.youtube.com/watch?v=XV9JLihcdb4", "title": "Surgical Airway Mindset and Preparation", "ch": "Cliff Reid"}], "pastabos": "", "esme": ["Indikacija – CICO: neįmanoma nei intubuoti, nei oksigenuoti (kaukė, supraglotinė priemonė, intubacija – „geriausios pastangos“ išnaudotos), hipoksija gilėja.", "Dažniausia klaida – per vėlai pripažinti poreikį. Sprendimą aiškiai paskelbti, trumpai (~10 s) aptarti su komanda ir iškart vykdyti.", "Rinkinys: skalpelis (Nr. 10), guminis elastingas bužas, trachėjos vamzdelis su manžete (VD 6,0 mm). Deguonis per viršutinius kvėpavimo takus tiekiamas visą laiką.", "Nedominuojančia ranka stabilizuokite gerklas ir nustatykite krikotiroidinę membraną; jei nėra kaklo traumos – galvą atloškite.", "Membrana čiuopiama: skersinis dūris, ašmenis pasukti 90° (aštrus kraštas kaudaliai), bužas palei ašmenis į trachėją, juo įvesti vamzdelį.", "Membrana nečiuopiama: 8–10 cm vertikalus odos pjūvis, bukas preparavimas pirštais, stabilizuoti gerklas ir tęsti kaip aukščiau.", "Padėtį patvirtinti kapnografija, krūtinės judesiais, auskultacija. Komplikacijos: kraujavimas, užpakalinės trachėjos sienos pažeidimas, vamzdelis už trachėjos."], "tccc": ["Kitoms priemonėms nepadėjus ir obstrukcijai nevaldomai (veido lūžiai, kvėpavimo takų sužalojimas, kraujas, deformacija, nudegimai) – chirurginė krikotiroidotomija.", "Atvira technika (su bužu ar standartinė), flanšinė kaniulė su manžete: VD 6–7 mm, išorinis < 10 mm, 5–8 cm trachėjoje; tikrinti EtCO₂; sąmoningam – lidokainas."], "esmeSrc": ["ETC vadovas, 3 sk.", "TCCC 2026, TFC 4f (Airway)"]},
  {"id": 19, "sritis": "Pirminė apžiūra", "potema": "B (Breathing)", "pav": "Hipotermijos vertinimas", "kam": "Visiems", "teorija": "Atpažinimas, temperatūros matavimas, pradiniai veiksmai.", "praktika": "Praktinis vertinimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku vertinti dėl hipotermijos</li></ul>", "saltT": "", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=WxgUb70qCQs", "title": "Life Threatening Hypothermia Emergency", "ch": "Larry B. Mellick, MD"}], "pastabos": "", "esme": ["Hipotermija – centrinė kūno temperatūra < 35 °C (Flight Med: lengva 32–35 °C, vidutinė 30–32 °C, sunki < 30 °C).", "Matuokite centrinę temperatūrą: stemplės ar šlapimo pūslės kateterio jutikliai tikslesni; tiesiosios žarnos temperatūra atsilieka nuo pokyčių.", "Lengva – drebulys, tachikardija, tachipnėja; vidutinė – mieguistumas, sumišimas, neaiški kalba; sunki – drebulys liaujasi, koma, bradikardija, aritmijos.", "Traumos pacientui hipotermija su acidoze, koaguliopatija ir hipokalcemija sudaro mirtiną „deimantą“; ją gilina kraujo netekimas, šlapi drabužiai, šalti skysčiai.", "Nuo atvykimo: šilta patalpa ir pašildyti skysčiai, šlapius drabužius nuimti, apžiūrėtą pacientą uždengti, priverstinio oro šildymo antklodė.", "Drebulys stiprina skausmą; hipotermijai analgetikus skirkite ypač atsargiai. Esant ryškiai hipotermijai SpO₂ rodmenys gali klaidinti.", "Elkitės švelniai, patikrinkite gliukozę; vidutinei–sunkiai – EKG stebėsena. Šildant galimas tolesnis temperatūros kritimas ir staigi hipotenzija."], "tccc": ["Anksti ir aktyviai: izoliuoti nuo šalto paviršiaus ir vėjo, šlapius drabužius keisti sausais; šildymo antklodė ant priekinio liemens ir pažastyse – ne tiesiai ant odos.", "Pacientą apgaubti nepralaidžiu maišu, kuo greičiau – izoliuota sistema (pvz., miegmaišis); IV/IO skysčius leisti per baterinį šildytuvą (38 °C, iki 150 ml/min)."], "esmeSrc": ["ETC vadovas, 2 sk.", "Flight Med – Environmental Emergencies", "Flight Med – Ballistics Trauma / Blast Injuries", "TCCC 2026, TFC 5c, 7 (Hypothermia Prevention)"]},
  {"id": 20, "sritis": "Pirminė apžiūra", "potema": "B/C (B apžiūri, diržą deda B ir C)", "pav": "Dubens stabilumo vertinimas ir dubens diržas", "kam": "Visiems", "teorija": "Trauminio kraujavimo ir dubens nestabilumo atpažinimas.", "praktika": "Vertinimas ir diržo uždėjimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku vertinti dubenį – stabilus ar nestabilus</li><li>Moku uždėti dubens diržą</li></ul>", "saltT": "ETC vadovas, 7 sk. „Dubens trauma“", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Šokas be akivaizdaus išorinio kraujavimo – ieškokite kraujo krūtinėje, pilve, dubenyje ir aplink ilguosius kaulus („kraujas ant grindų ir dar keturios vietos“).", "B įvertina dubens stabilumą ir apžiūri tarpvietę bei lytinius organus. Nestabilus dubuo ar kraujas tarpvietėje – dubens diržas, kurį deda B kartu su C.", "Dubens nešoktelėkite (ETC) – galite išstumti krešulį; įtarus lūžį – diržas (B + C), vėliau rentgenas ar KT (kompiuterinė tomografija).", "Turniketas ant šlaunies dėl amputacijos ar atviro lūžio neatmeta dubens lūžio – nepamirškite diržo. Apatinės galūnės amputacija dažnai su dubens trauma.", "Nestabilus dubens lūžis: vertimas ant šono gali padidinti žalą ar išstumti krešulį – verskite atsargiai, bet nugaros žaizdų nepraleiskite.", "Dubens lūžis su šoku – tikėtina transfuzija: ruoškite kraujo komponentus.", "Antrinėje apžiūroje esant dubens lūžiui – tiesiosios žarnos ir makšties apžiūra: praleisti vidiniai atviri lūžiai didina komplikacijas ir mirties riziką."], "tccc": ["Dubens diržas įtarus lūžį: sunki buka ar sprogimo trauma + dubens skausmas, didelė apatinės galūnės (beveik) amputacija, lūžio požymiai, be sąmonės ar šokas."], "esmeSrc": ["ETC vadovas, 1 sk. (fiksacijos klaidos)", "ETC vadovas, 2 sk. (+ priedas)", "ETC vertinimo lapas", "Flight Med – Ballistics Trauma / Blast Injuries", "TCCC 2026, TFC 6a.1", "Kuopos ETC algoritmas"]},
  {"id": 21, "sritis": "Pirminė apžiūra", "potema": "C (Circulation)", "pav": "PVK įvedimas ir neveikiančio PVK atpažinimas", "kam": "Medicinos personalui", "teorija": "Indikacijos, komplikacijos, tinkamos venos.", "praktika": "PVK įvedimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku įvesti periferinį venos kateterį (PVK) ir atpažinti neveikiantį PVK</li></ul>", "saltT": "ETC vadovas, 5 sk. „Šokas“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=rYyj4v-edic", "title": "29 Pediatric IV Tricks", "ch": "Larry B. Mellick, MD", "note": "Vaikų PVK, bet patarimai tinka ir suaugusiems"}], "pastabos": "", "esme": ["C, vos atvykus pacientui, be A nurodymo įveda 16–18 G PVK ir kiekvienam pacientui nustato kraujo grupę bei gliukozę.", "Tikslas – bent 2 didelio kalibro PVK arba IO adata. Jei PVK greitai įvesti nepavyksta – nedelsiant IO.", "Kraujo perpylimui – 18 G ar didesnio spindžio (16 G, 14 G) PVK arba IO; kraujas šildomas, greitam perpylimui naudojamas spaudimo maišas.", "Prieš invazines procedūras (pleuros drenavimą, RSI) įsitikinkite, kad venos prieiga yra ir veikia.", "Hipovolemija sumažina venų skersmenį; centrinės venos kaniuliacijai aukso standartas – ultragarso kontrolė (pagal kompetenciją)."], "tccc": ["IV/IO prieiga – esant hemoraginiam šokui ar didelei jo rizikai arba kai vaistų negalima duoti per burną. Pirmenybė – 18 G PVK arba „saline lock“.", "Jei kraujagyslių prieiga reikalinga, bet IV būdu greitai jos gauti nepavyksta – naudoti IO."], "esmeSrc": ["ETC vadovas, 2 sk.", "ETC vadovas, 3–4 sk.", "ETC vertinimo lapas (C narys, gydymo kokybė)", "Flight Med – Ballistics Trauma", "TCCC 2026, TFC 6c", "Kuopos ETC algoritmas"]},
  {"id": 22, "sritis": "Pirminė apžiūra", "potema": "C (Circulation)", "pav": "Intrakaulinė prieiga", "kam": "Pagal kompetenciją", "teorija": "Indikacijos, vietos, komplikacijos.", "praktika": "IO adatos įvedimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku įdurti intrakaulinę adatą</li></ul>", "saltT": "ETC vadovas, 5 sk. „Šokas“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=SYfVFq0rc7c", "title": "Proximal Humerus Intraosseous Needle Procedure", "ch": "Larry B. Mellick, MD"}, {"url": "https://www.youtube.com/watch?v=YXfyL8kvFTg", "title": "6 Mistakes in Awake Adult IO Infusion", "ch": "Larry B. Mellick, MD"}, {"url": "https://www.youtube.com/watch?v=3L5vSKyqi6w", "title": "Humeral Intraosseous - Keep 'Em In And Keep 'Em Straight", "ch": "Cliff Reid"}], "pastabos": "", "esme": ["IO – atsarginė prieiga: jei PVK greitai įvesti nepavyksta, IO įvedama nedelsiant (C narys, be A nurodymo).", "IO rinkinį paruoškite iš anksto – jis yra pasiruošimo ir RSI kontrolinio sąrašo dalis.", "Per IO galima leisti skysčius, kraujo komponentus ir IV vaistus (TCCC TXA, kalcį, ketaminą nurodo leisti IV / IO).", "Kraujo perpylimui tinka IO arba 18 G ar didesnio spindžio (16 G, 14 G) PVK; kraujas šildomas, greitam perpylimui – spaudimo maišas.", "Gaivinimo skysčius per IV / IO leiskite per šildytuvą – hipotermijos prevencija.", "Gydymo kokybės tikslas – bent 2 didelio kalibro PVK arba IO adata."], "tccc": ["Jei kraujagyslių prieiga reikalinga, bet IV būdu greitai jos gauti nepavyksta – naudoti IO."], "esmeSrc": ["ETC vadovas, 2–3 sk.", "ETC vertinimo lapas (C narys, gydymo kokybė)", "Flight Med – Ballistics Trauma", "TCCC 2026, TFC 6c, 6e, 7h", "Kuopos ETC algoritmas"]},
  {"id": 23, "sritis": "Pirminė apžiūra", "potema": "C (Circulation)", "pav": "Kraujo grupės nustatymas ir kraujo transfuzija", "kam": "Medicinos personalui", "teorija": "Transfuzijos sauga, kraujo komponentai, indikacijos.", "praktika": "Transfuzijos paruošimas ir atlikimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku nustatyti kraujo grupę</li><li>Moku atlikti kraujo transfuziją</li></ul><h3>Mokymosi temos</h3><a class=\"row\" href=\"#/p/kraujas\">Kraujo suderinamumas<span class=\"ar\">›</span></a>", "saltT": "ETC vadovas, 5 sk. „Šokas“", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["C nustato kraujo grupę kiekvienam pacientui iškart atvykus (kartu su gliukoze) ir ruošia kraujo komponentus.", "Indikacijos – hemoraginis šokas; tipinės situacijos: amputacija, nekompresuojamas penetruojantis liemens ar jungties sužalojimas, dubens lūžis, koaguliopatija.", "Pirmenybė – mažo titro O pilnas kraujas, toliau plazma : eritrocitai : trombocitai 1:1:1 arba plazma : eritrocitai 1:1. Masinis kraujavimas – aktyvuoti protokolą.", "Eritrocitų universalus donoras – O Rh−, plazmos – AB. Neištirtą ar grupei specifinį šviežią pilną kraują – tik mediko nurodymu (hemolizės rizika).", "Kartu su perpylimu: maksimaliai stabdyti kraujavimą, gydyti įtampos pneumotoraksą, užtikrinti kvėpavimo takus, šildyti; prieiga – 18 G ar didesnė PVK arba IO.", "Citratas suriša kalcį – perpilant užtikrinkite kalcį (dozė – vaistų skiltyje). Būklę vertinkite po kiekvieno vieneto.", "Ūminė hemolizinė reakcija (dusulys, hipotenzija, hemoglobinurija) – perpylimą nedelsiant stabdyti. Galimos ir febrilinė, alerginė reakcija, TACO, TRALI."], "tccc": ["Eilė: šaltai laikytas mažo titro O pilnas kraujas → ištirtų donorų šviežias mažo titro O → 1:1:1 → 1:1 → vien plazma ar eritrocitai. Nesant Rh− – Rh+.", "Vertinti po kiekvieno vieneto; gaivinti, kol čiuopiamas radialinis pulsas, pagerėja sąmonė ar sAKS pasiekia 100 mm Hg. Po pirmojo vieneto – kalcis IV/IO."], "esmeSrc": ["ETC vadovas, 1–2 sk.", "ETC vertinimo lapas (C narys, gydymo kokybė)", "Kraujo suderinamumo lentelė (kuopos medžiaga)", "Flight Med – Ballistics Trauma", "Flight Med – Laboratory Values", "TCCC 2026, TFC 6e", "Kuopos ETC algoritmas"]},
  {"id": 24, "sritis": "Pirminė apžiūra", "potema": "C (Circulation)", "pav": "IV vaistų paruošimas ir leidimas", "kam": "Medicinos personalui", "teorija": "Ketaminas, rokuroniumas, TXA, fentanilis, morfinas, kalcis, naloksonas, ondansetronas, metoklopramidas – pagal vietines SOP.", "praktika": "Vaistų paruošimo praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku pritraukti ir suleisti vaistus į veną, žinau, kokios turi būti leidžiamos dozės: ketaminas, rokuroniumas, traneksamo rūgštis, fentanilis, morfinas, kalcio gliukonatas, naloksonas, ondansetronas, metoklopramidas</li></ul><h3>Susiję vaistai</h3><a class=\"row\" href=\"#/vaistas/ketaminas\">Ketaminas<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/rokuroniumas\">Rokuroniumas<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/txa\">Traneksamo rūgštis<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/fentanilis\">Fentanilis<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/morfinas\">Morfinas<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/kalcis\">Kalcio gliukonatas<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/naloksonas\">Naloksonas<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/ondansetronas\">Ondansetronas<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/metoklopramidas\">Metoklopramidas<span class=\"ar\">›</span></a><h3>Mokymosi temos</h3><a class=\"row\" href=\"#/p/skiedimas\">Vaistų skiedimo lentelės<span class=\"ar\">›</span></a>", "saltT": "", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Prieš traukdami patikrinkite vaistą ir ampulės stiprumą (pvz., ketaminas 50 ar 100 mg/ml) – nuo jo priklauso, kiek ml suleisti.", "Žinokite: švirkšto dydį, kiek vaisto ir skiediklio pritraukti, galutinę koncentraciją švirkšte ir kiek suleisti.", "Paruoštus vaistus laikykite paženklintuose švirkštuose.", "Dozę apskaičiuokite iš anksto, analgetikus titruokite mažais kiekiais: šoko metu poveikis uždelstas, kartojamos dozės gali sukelti kolapsą.", "Greitis – pagal vaistą: RSI vaistai (indukcijos ir relaksantas) – greitai į veikiančią IV liniją; TXA, fentanilis, ondansetronas, metoklopramidas – lėtai.", "Nesuderinamų vaistų (pvz., kalcio ir ceftriaksono) kartu neleiskite; paeiliui – tik gerai praplovus liniją arba į skirtingas vietas.", "Paskyrimą pakartokite garsiai (uždaro ciklo komunikacija), svarbią informaciją patikrinkite dar kartą. Dozės – skiltyje Vaistai."], "tccc": ["Kalcis skiriamas po pirmojo perpilto kraujo produkto (TFC 6e; dozė – skiltyje Vaistai)."], "esmeSrc": ["ETC vadovas, 2–3 sk.", "ETC įgūdžių skiedimo lentelė", "ETC vertinimo lapas", "Vaistai (PCS)", "TCCC 2026, TFC 6e"]},
  {"id": 25, "sritis": "Pirminė apžiūra", "potema": "C (Circulation)", "pav": "Infuzomato paruošimas ilgalaikei infuzijai", "kam": "Medicinos personalui", "teorija": "Noradrenalinas, morfinas, ketaminas, fentanilis, TXA – pagal vietines SOP.", "praktika": "Pompos paruošimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Paprašytas ir instruktuotas galiu paruošti ir paleisti infuzomatą (švirkštinę pompą) ilgalaikei infuzijai: noradrenalinas, morfinas, ketaminas, fentanilis, traneksamo rūgštis</li></ul><h3>Susiję vaistai</h3><a class=\"row\" href=\"#/vaistas/noradrenalinas\">Noradrenalinas<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/morfinas\">Morfinas<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/ketaminas\">Ketaminas<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/fentanilis\">Fentanilis<span class=\"ar\">›</span></a><a class=\"row\" href=\"#/vaistas/txa\">Traneksamo rūgštis<span class=\"ar\">›</span></a><h3>Mokymosi temos</h3><a class=\"row\" href=\"#/p/skiedimas\">Vaistų skiedimo lentelės<span class=\"ar\">›</span></a>", "saltT": "", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["ETC: infuzomatą (švirkštinę pompą) ruošiate paprašytas ir instruktuotas – paskyrimą pakartokite garsiai (uždaro ciklo komunikacija).", "Patikrinkite tirpalo koncentraciją: tas pats vaistas ruošiamas skirtingai (pvz., noradrenalinas 40 ar 80 mcg/ml) – tai pačiai dozei ml/val. skiriasi.", "Greitį (ml/val.) skaičiuokite pagal koncentraciją švirkšte, ne ampulėje. Švirkštą paženklinkite.", "Noradrenalinas – tik atkūrus tūrį (hemoraginiam šokui pirmiausia kraujas); skiedžiamas 5 % gliukoze; PCS – per CVK, ekstravazacija sukelia nekrozę.", "Titruokite pagal tikslą (ETC): hemoraginis šokas be galvos traumos – vid. AKS 65 mm Hg; galvos smegenų trauma – sAKS 110–120 (TCCC lauke – > 100) mm Hg.", "Noradrenalino infuzijos staiga nenutraukite – mažinkite palaipsniui. Opioidų infuzija – stebėkite kvėpavimą (antagonistas – naloksonas).", "Stebėkite AKS, EKG, SpO₂ ir infuzijos vietą. Dozės ir skiedimas – skiltyje Vaistai."], "tccc": [], "esmeSrc": ["ETC įgūdžių įsivertinimas ir skiedimo lentelė", "ETC vertinimo lapas", "ETC vadovas, 3 sk.", "Vaistai (PCS)"]},
  {"id": 26, "sritis": "Pirminė apžiūra", "potema": "C (Circulation)", "pav": "Turniketo konversija ir hiperkalemijos prevencijos principai", "kam": "Medicinos personalui", "teorija": "Indikacijos, laikas, komplikacijų prevencija.", "praktika": "Turniketo konversijos praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Žinau, kokius vaistus skirti siekiant išvengti turniketo konversijos komplikacijos – hiperkalemijos</li><li>Moku atlikti turniketo konversiją</li></ul>", "saltT": "ETC vadovas, 10 sk. „Galūnių ir minkštųjų audinių trauma“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=C0VUMvjBSMA", "title": "Severe Hyperkalemia Emergency", "ch": "Larry B. Mellick, MD", "note": "Hiperkalemijos atpažinimas ir gydymas"}], "pastabos": "", "esme": ["Konversija – turniketą pakeisti hemostatiniu ar spaudžiamuoju tvarsčiu, kai: nėra šoko, žaizdą galima atidžiai stebėti ir tai nėra amputacija.", "Siekite konversijos per < 2 val., jei kraujavimą galima sustabdyti kitaip. Ilgiau nei 6 val. uždėto turniketo nenuimkite be atidaus stebėjimo ir laboratorijos.", "Pirma atidenkite žaizdą ir įvertinkite, ar turniketas reikalingas. Ant uniformos uždėtą – antrą ant odos 5–7,5 cm virš žaizdos, tada atlaisvinkite pirmą.", "Po konversijos stebėkite, ar kraujavimas neatsinaujino. ETC: konversiją antrinėje apžiūroje atlieka C, padeda B.", "Konversijos komplikacija – hiperkalemija (kalio daugėja ir dėl rabdomiolizės, acidozės, inkstų nepakankamumo, transfuzijų): gresia aritmijos – stebėkite EKG.", "Hiperkalemija su EKG pokyčiais – pirmiausia kalcis IV (širdies apsauga, ERC); kalio kiekį mažina gliukozė su insulinu ir salbutamolis – skiria medikas pagal SOP.", "ETC kokybės kriterijus: konversija – kai saugu; aptariamas hiperkalemijos ir inkstų nepakankamumo rizikos mažinimas."], "tccc": ["Praėjus > 2 val. nuo uždėjimo, ASM/CLS apmokyti konversijos nebando be CMC/CPP ar kito pažangaus mediko nurodymo – palieka turniketą ir stebi.", "Laikus (uždėjimo, perdėjimo, konversijos, nuėmimo) užrašykite TCCC kortelėje; uždėjimo laiką – ir ant turniketo, permanentiniu žymekliu."], "esmeSrc": ["TCCC 2026, TFC 6a (Bleeding)", "ETC įgūdžių įsivertinimas", "ETC vertinimo lapas", "Flight Med – Laboratory Values", "ERC 2021 (ypatingos aplinkybės – hiperkalemija)"]},
  {"id": 27, "sritis": "Pirminė apžiūra", "potema": "C (Circulation)", "pav": "Infuziniai tirpalai pagal indikacijas", "kam": "Medicinos personalui", "teorija": "Manitolis, NaCl 3 %, gliukozė + insulinas, Ringerio laktatas – pagal vietines SOP.", "praktika": "Infuzijos paruošimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Žinau, kokiais atvejais skirčiau ir galėčiau atlikti infuziją į veną: manitolis, NaCl 3 %, gliukozė 5 % + insulinas 0,1 VV/kg, Ringerio laktatas</li></ul><h3>Susiję vaistai</h3><a class=\"row\" href=\"#/vaistas/nacl-hipert\">Hipertoninis NaCl<span class=\"ar\">›</span></a>", "saltT": "", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=C0VUMvjBSMA", "title": "Severe Hyperkalemia Emergency", "ch": "Larry B. Mellick, MD", "note": "Gliukozė su insulinu hiperkalemijai"}], "pastabos": "", "esme": ["Hemoraginiam šokui pirmenybė – kraujo komponentams; venkite skysčių pertekliaus.", "Ringerio laktatas – nudegus > 20 % kūno paviršiaus (taip pat tinka NaCl 0,9 % ar Hextend); esant ir hemoraginiam šokui, pirmiausia gaivinama nuo jo.", "Skysčius šildykite: šalti ir dideli skaidrių skysčių kiekiai didina hipotermiją ir acidozę; daug NaCl 0,9 % – hiperchloreminė acidozė.", "ETC lapas: galvos traumai – manitolis arba 3 % NaCl ir 30° galvūgalis; TCCC – NaCl tik esant išvaržos požymiams (ne profilaktiškai), galvūgalį kelti, jei nėra šoko.", "Hipertoninis NaCl – ne gaivinimo (tūrio) skystis; TCCC – tik esant smegenų išvaržos požymiams, ne profilaktiškai.", "Gliukozė su insulinu mažina kalio kiekį – taikoma hiperkalemijai (pvz., po turniketo konversijos).", "Dozės: hipertoninis NaCl – skiltyje Vaistai; manitolio, gliukozės su insulinu ir Ringerio laktato ten nėra – pagal vietines SOP."], "tccc": ["Hipertoninis NaCl – tik esant išvaržos požymiams (asimetriški ar fiksuoti išsiplėtę vyzdžiai, patologinė laikysena); po jo praplauti; ekstravazacijos atveju nutraukti.", "Hemoraginiam šokui: visas kraujas → plazma ir eritrocitai (+ trombocitai) → plazma ar eritrocitai atskirai. Nesant šoko IV skysčiai nebūtini."], "esmeSrc": ["ETC įgūdžių įsivertinimas", "ETC vertinimo lapas", "ETC vadovas, 2 sk.", "TCCC 2026, TFC 6e, 8d, 15e", "Flight Med – Burn Management, Laboratory Values, Blast Injuries, Ballistics Trauma", "Vaistai"]},
  {"id": 28, "sritis": "Antrinė apžiūra", "potema": "A", "pav": "Retrobulbarinės hematomos atpažinimas ir lateralinė kantotomija", "kam": "Pagal kompetenciją", "teorija": "Požymiai, skubi pagalba, procedūros principai.", "praktika": "Procedūros treniruoklis", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Atpažįstu retrobulbarinės hematomos (kraujavimo už akies obuolio) požymius</li><li>Moku atlikti lateralinę kantotomiją (retrobulbarinės hematomos gydymas)</li></ul>", "saltT": "", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=VBg0ST7upkg", "title": "Lateral Canthotomy and Cantholysis", "ch": "Larry B. Mellick, MD"}, {"url": "https://www.youtube.com/watch?v=bUAagMd_Q8A", "title": "Emergency Lateral Canthotomy and Cantholysis", "ch": "Larry B. Mellick, MD"}], "pastabos": "", "esme": ["Retrobulbarinė hematoma – kraujavimas už akies obuolio; ETC ją gydo lateraline kantotomija (atlieka kompetentingas narys).", "Požymiai: skausmingas išsikišęs akies obuolys, ribotas judrumas, įtempta orbita, blogėjantis regėjimas, aferentinis vyzdžio defektas – skubi kantotomija (regėjimas žūva per 1,5–2 val.).", "Antrinėje apžiūroje A apžiūri akių obuolius dėl retrobulbarinės hematomos; esant įtarimui – lateralinė kantotomija.", "Akys: vyzdžių dydis, simetrija ir reakcija į šviesą, akių judesiai, svetimkūnis, akies obuolio trauma, kontaktiniai lęšiai.", "Akių nudegimai – skubi būklė.", "Akies (orbitos) kompartmento sindromą gali sukelti ir masyvus skysčių gaivinimas (pvz., esant dideliems nudegimams)."], "tccc": ["Įtarus penetruojančią akies traumą: greitas regėjimo aštrumo testas (užrašyti), standus akies skydelis – NE spaudžiamasis tvarstis; antibiotikai (Vaistai)."], "esmeSrc": ["ETC įgūdžių įsivertinimas", "ETC vertinimo lapas", "ETC vadovas, 2 sk.", "Flight Med – Burn Management", "TCCC 2026, TFC 9 (Penetrating Eye Trauma)", "RVEEH retrobulbarinės hematomos gairės (2021)"]},
  {"id": 29, "sritis": "Antrinė apžiūra", "potema": "A", "pav": "Priekinė ir užpakalinė nosies tamponada", "kam": "Pagal kompetenciją", "teorija": "Indikacijos ir komplikacijos.", "praktika": "Tamponavimo praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku tamponuoti priekinę ir užpakalinę nosies landą esant veido traumai</li></ul>", "saltT": "", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Indikacija – nuolatinis kraujavimas į nosies ar burnos ertmę po veido ir žandikaulių traumos; priekinė ir užpakalinė tamponada – paprastai pirmasis pasirinkimas.", "Prieš procedūrą užtikrinkite kvėpavimo takus – trachėjos intubacija arba chirurginis kvėpavimo takas.", "Lūžgalius reponuokite; apatinį žandikaulį fiksuokite kaklo įtvaru, viršutinį – dantų blokeliais; tik tada tamponuokite vidurinę veido dalį.", "Užpakalinė: komercinis balionas arba 12 Fr Foley į pažeistą landą; pripūsti 5–7 ml fiziol. tirpalo, patraukti į priekį, kol užsifiksuos, papildyti 5–7 ml.", "Pasislinkus minkštajam gomuriui – dalį tirpalo išleiskite. Kateterį fiksuokite bambos spaustuku prie šnervės, nosies audinius apsaugokite marle (spaudimo nekrozė).", "Neužtekus – į priekines nosies ertmes vazelino marlė; kraujuojant iš burnos – burnos ertmę tamponuokite marle.", "Komplikacijos: pneumocefalija, lūžgalių pasislinkimas į akiduobę ar kaukolės ertmę. Nesiliaujant – embolizacija ar išorinės miego arterijos perrišimas."], "tccc": [], "esmeSrc": ["ETC vadovas, 3 sk. (masinis kraujavimas po veido ir žandikaulių traumos)", "ETC vertinimo lapas"]},
  {"id": 30, "sritis": "Antrinė apžiūra", "potema": "A", "pav": "Dantų blokeliai (dental blocks) ir nosies pertvaros hematoma", "kam": "Pagal kompetenciją", "teorija": "Kas tai, kada taikoma, atpažinimas ir drenavimo principai.", "praktika": "Praktinė technika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku įdėti dantų blokelius (dental blocks), žinau, kas tai yra ir kada taikoma</li><li>Galiu atpažinti nosies pertvaros hematomą ir moku ją drenuoti</li></ul>", "saltT": "", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Dantų (kandimo) blokeliai įtvirtina viršutinį žandikaulį prie apatinio – taikoma esant veido kaulų nestabilumui ir kraujavimui (A nurodo, atlieka B).", "Pirma kaklo įtvaras – jis fiksuoja apatinį žandikaulį; jei jau uždėtas, palikite. Masyviai kraujuojant kvėpavimo takai užtikrinami prieš procedūrą.", "Blokelį laikykite tarp nykščio ir vidurinio piršto, rankena nuo burnos; lėtai stumkite gilyn, tvirtai įspauskite tarp krūminių dantų. Kartokite kitoje pusėje.", "Stabilizavus blokeliais ir kaklo įtvaru – vidurinės veido dalies (nosies) tamponada (žr. įgūdį #29).", "Kita paskirtis: įdėjus laringinę kaukę ar laringinį vamzdelį, jei įmanoma, kandimo bloką dėkite šalia vamzdelio ir kartu pritvirtinkite.", "Nosies pertvaros hematoma tikrinama antrinėje apžiūroje kartu su kraujavimu ir likvorėja iš nosies; drenuoja kompetentingas B pagal A nurodymą."], "tccc": [], "esmeSrc": ["ETC vadovas, 2–3 sk.", "ETC vertinimo lapas", "ETC įgūdžių įsivertinimas"]},
  {"id": 31, "sritis": "Antrinė apžiūra", "potema": "B", "pav": "Kaklo imobilizacija", "kam": "Visiems pagal situaciją", "teorija": "Indikacijos ir saugus imobilizavimas.", "praktika": "Imobilizacijos praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku imobilizuoti kaklą</li></ul>", "saltT": "ETC vadovas, 9 sk. „Stuburo ir nugaros smegenų trauma“", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Atvykusiam be imobilizacijos – rankinė stabilizacija (MILS); įvertinus kvėpavimo takus – pusiau standus įtvaras su blokais ir juostomis arba vakuuminis čiužinys.", "Prieš dėdamas įtvarą B apžiūri kaklą: trachėjos padėtis, žaizdos, hematomos, kraujas ir skausmingumas po kaklu.", "Kvėpavimo takų veiksmai – išlaikant galvos ir kaklo ašį. Prieš intubaciją: MILS, tada nuimti juostas, blokus ir įtvaro priekinę dalį; MILS – kol įtvaras vėl uždėtas.", "Atidarant įtvarą ir išlaikant MILS reikia 3 žmonių. Įtvaras riboja burnos atvėrimą – kvėpavimo takai tampa sunkesni.", "Įtvaras gali trikdyti kvėpavimo takus, spausti patinusius audinius, kelti skausmą. Jei netinka (maži vaikai, senyvi su artritu) – volai iš antklodžių ar rankšluosčių.", "Apverčiant (B + C) apžiūrėkite nugarą ir palpuokite stuburo vidurio liniją dėl skausmingumo, jei pacientas sąmoningas.", "Stuburo lentą ar mentės neštuvus pašalinkite kuo anksčiau – mažiau skausmo ir spaudimo žaizdų rizika."], "tccc": ["Vien penetruojanti trauma – kaklo stuburo stabilizacija nebūtina (TFC 4h).", "Galvos smegenų trauma (intrakranijinio spaudimo mažinimas): atlaisvinti kaklo įtvarą, galvą laikyti tiesiai, nesukant kaklo (TFC 8c)."], "esmeSrc": ["ETC vadovas, 2–3 sk.", "ETC vertinimo lapas", "Flight Med – Patient Packaging", "TCCC 2026, TFC 4h, 8c"]},
  {"id": 32, "sritis": "Antrinė apžiūra", "potema": "B/C", "pav": "Žaizdų ir nudegimų tvarkymas", "kam": "Visiems", "teorija": "Pirminis žaizdų ir nudegimų įvertinimas.", "praktika": "Tvarsčių ir žaizdų priežiūros praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku tvarkyti žaizdas / nudegimus</li></ul>", "saltT": "ETC vadovas, 10 sk. „Galūnių ir minkštųjų audinių trauma“", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["Pirmiausia gyvybei pavojingos būklės: tai traumos pacientas su nudegimais, o ne nudegęs su sužalojimais – nesiblaškykite dėl nudegimų.", "Ieškokite visų žaizdų: apverčiant (B + C) apžiūrėkite nugarą ir sėdmenis, nepraleiskite dūrio žaizdų. Patikrinkite stabligės statusą.", "Žaizdas sutvarstykite; atsinaujinus šokui – patikrinkite visas kraujavimo stabdymo priemones. Evisceracijos jėga atgal nekiškite.", "Nudegimo plotas – devynių taisyklė (tik II–III laipsnio nudegimai); delnas su pirštais ≈ 1 %. TCCC – apvalinti iki artimiausių 10 %.", "Uždenkite sausu steriliu tvarsčiu arba skaidria plastikine plėvele – ją dėkite išilginėmis juostomis, kad nesuveržtų galūnių.", "Nudegę ypač greitai šąla: aktyvi hipotermijos prevencija; nudegus > 20 % – šilumą atspindintis apvalkalas ar antklodė iš hipotermijos rinkinio.", "Veido nudegimas uždaroje erdvėje – įkvėpimo trauma: stebėkite kvėpavimo takus ir SpO₂. Žiediniai nudegimai – tikrinkite distalinį pulsą."], "tccc": ["Nudegus > 20 % – skysčiai, kai tik yra IV / IO (RL, NaCl 0,9 % ar Hextend ≤ 1000 ml): %TBSA × 10 ml/val. (40–80 kg), +100 ml/val. kas 10 kg virš 80 kg.", "Antibiotikai – visoms atviroms kovinėms žaizdoms, ne vien dėl nudegimų (dozės – Vaistai). Visas TCCC intervencijas galima atlikti per nudegusią odą."], "esmeSrc": ["ETC vadovas, 2 sk.", "ETC vertinimo lapas", "TCCC 2026, TFC 6e, 12–15 (Burns)", "Flight Med – Burn Management", "Flight Med – Ballistics Trauma"]},
  {"id": 33, "sritis": "Antrinė apžiūra", "potema": "B/C", "pav": "Galūnės imobilizacija", "kam": "Visiems", "teorija": "Indikacijos, neurovaskulinio statuso kontrolė.", "praktika": "Įtvaro uždėjimas", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku imobilizuoti galūnę</li></ul>", "saltT": "ETC vadovas, 10 sk. „Galūnių ir minkštųjų audinių trauma“", "nuorT": "", "saltP": "", "nuorP": "", "video": [{"url": "https://www.youtube.com/watch?v=cdodDRv9Nms", "title": "Reduction & Splinting of Forearm Fractures--Quick Version", "ch": "Larry B. Mellick, MD"}], "pastabos": "", "esme": ["Lūžius imobilizuokite anksti: mažėja skausmas, kraujavimas iš lūžio, neurovaskuliniai ir antriniai audinių pažeidimai (pvz., odos nekrozė), riebalų embolija.", "C vertina galūnes dėl lūžių ir imobilizuoja įtariamas vietas, B padeda.", "Vertinkite: deformacija, skausmingumas, žaizdos ir atviri lūžiai, sąnarių stabilumas, jutimai ir judesiai (raumenų jėga).", "Po imobilizacijos vėl patikrinkite distalinį pulsą, jutimus ir judesius.", "Šoko požymiai be matomo kraujavimo – ieškokite kraujo krūtinėje, pilve, dubenyje ir aplink ilguosius kaulus (pvz., šlaunikaulį).", "Atvirą lūžį sutvarstykite; antibiotikai rekomenduojami visoms atviroms kovinėms žaizdoms (dozės – skiltyje Vaistai).", "Sutraiškymas, žiediniai nudegimai – kompartmento sindromo rizika. Ankstyvi požymiai: stiprėjantis skausmas, ypač tempiant pasyviai, įtempta galūnė; pulsas dingsta vėlai."], "tccc": ["„Splint fractures and re-check pulses“ – imobilizuokite lūžius ir pakartotinai patikrinkite pulsą (TFC 16)."], "esmeSrc": ["ETC vadovas, 2 sk.", "ETC vertinimo lapas", "TCCC 2026, TFC 12, 16", "Flight Med – Ballistics Trauma", "Flight Med – Blast Injuries", "Flight Med – Burn Management"]},
  {"id": 34, "sritis": "Antrinė apžiūra", "potema": "B/C", "pav": "ŠPK įvedimas", "kam": "Pagal kompetenciją", "teorija": "Indikacijos ir procedūros principai.", "praktika": "Procedūros praktika", "aprasymas": "<h3>ETC įsivertinimo teiginiai</h3><ul><li>Moku įvesti ŠPK</li></ul>", "saltT": "", "nuorT": "", "saltP": "", "nuorP": "", "video": [], "pastabos": "", "esme": ["ŠPK leidžia stebėti diurezę (gaivinimo pakankamumą) ir pastebėti hematuriją – inkstų, šlapimtakių ar šlapimo pūslės pažeidimo požymį.", "ETC vertinimo lape ŠPK įveda B antrinėje apžiūroje ir įvertina šlapimo spalvą bei drumstumą. Laikykitės aseptikos.", "Prieš įvesdami apžiūrėkite tarpvietę, lytinius organus ir šlaplės angą; kraujas tarpvietėje – dubens diržas (B + C), praneškite A.", "Dubens lūžis – galimas šlaplės pažeidimas: tik vienas atsargus patyrusio gydytojo bandymas; neina ar teka tik kraujas – balionėlio nepūsti, kviesti urologą.", "Suaugusiojo diurezės tikslas – 0,5–1 ml/kg/val.; nudegusiems skysčiai titruojami pagal valandinę diurezę.", "Tuščia šlapimo pūslė (UG) po skysčių gaivinimo – nepakankamas gaivinimas arba tebesitęsiantis kraujavimas.", "Prieš transportavimą ištuštinkite šlapimo maišą ir užrašykite diurezę."], "tccc": [], "esmeSrc": ["ETC vadovas, 2 sk.", "ETC vertinimo lapas", "Flight Med – Burn Management", "Flight Med – Abdominal Trauma", "BOAST 14 (BOA, 2016)"]}
];
